DIM Vendite() = {120,145,132,168,155,190,178,210,200,225,240,260}
DIM Costi() = { 90, 95, 88,100, 95,110,105,120,115,125,130,140}
Mesi$() = {"Gen","Feb","Mar","Apr","Mag","Giu","Lug","Ago","Set","Ott","Nov","Dic"}
Opts = NEW DICT
Opts.Set "title", "Andamento Vendite 2024"
Opts.Set "xlabel", "Mese"
Opts.Set "ylabel", "EUR (migliaia)"
Opts.Set "save", "report_vendite.png"
Opts.Set "legend", {"Vendite","Costi"}
Data = NEW DICT
Data.Set "x", Mesi$
Data.Set "series", {Vendite, Costi}
hChart = PLOTTING.PLOT Data, "line", Opts
PRINT "Grafico salvato in report_vendite.png"

DIM Categorie$() = {"Nord","Centro","Sud","Isole"}
DIM Fatturato() = {450, 320, 280, 150}
PLOTTING.PLOT Fatturato, "pie", {"title":"Fatturato per Area","labels":Categorie$}
PLOTTING.EXPORT "report_aree.png"
PRINT "Pie chart esportato."
DIM Trend() = {100,108,115,122,130}
PLOTTING.PLOT Trend, "line", {"title":"Trend crescita","save":"trend.pdf"}
PRINT "Line chart esportato in PDF."
